-- db			statecapitols
-- table			statecaps
-- Number of columns	11

CREATE TABLE `statecapitols`.`statecaps` (`id` SMALLINT NOT NULL AUTO_INCREMENT COMMENT 'index' , `State_name` TEXT NOT NULL COMMENT 'state name' , `Abbr` TEXT NOT NULL COMMENT 'abbreviation' , `Capital` TEXT NOT NULL COMMENT 'state capital' , `Most_pop` TEXT NOT NULL COMMENT 'largest city' , `Population` INT NOT NULL COMMENT 'Most populous city', `2nd_most_pop` TEXT NOT NULL COMMENT 'largest city' , `2nd_most_pop_pops` INT NOT NULL COMMENT '2nd most populous city', `3rd_most_pop` TEXT NOT NULL COMMENT 'largest city' , `3rd_most_pop_pops` INT NOT NULL COMMENT '3rd most populous city', PRIMARY KEY (`id`)) ENGINE = InnoDB COMMENT = 'USA state stats incl capitols';

ALTER TABLE `statecaps` ADD INDEX(`id`);



